const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;padding:10px;color:var(--ink);font-size:12px;line-height:1.4;overflow:hidden;background:transparent}\n.card *{box-sizing:border-box}\n.card button,.card input,.card textarea{font:inherit;color:var(--ink)}\n.card ::placeholder{color:var(--muted);opacity:.8}\n.card ::-webkit-scrollbar{width:4px}\n.card ::-webkit-scrollbar-thumb{background:var(--line);border-radius:2px}\n\n.btn{flex:1;min-width:0;height:30px;padding:0 8px;border-radius:9px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font-weight:600;font-size:12px;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.btn.add{flex:none;width:100%;border-style:dashed;background:transparent;color:var(--accent)}\n.btn:disabled{opacity:.5;cursor:default}\n.btn:focus-visible,.ib:focus-visible,.pick:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.home,.edit,.lib{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.top{grid-area:top;display:flex;flex-direction:column;gap:6px;min-width:0;flex:none}\n.list{grid-area:list;flex:1;min-height:0;min-width:0;overflow-y:auto;display:none;flex-direction:column;gap:6px;padding-right:2px}\n.actions{grid-area:act;display:flex;gap:6px;flex:none;min-width:0}\n.ttl{font-weight:700;font-size:15px;line-height:1.25;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;word-break:break-word}\n.ttl.untitled{color:var(--muted);font-weight:600}\n.dur{display:flex;align-items:baseline;flex-wrap:wrap;gap:0 1px;min-width:0}\n.dur-l{width:100%;color:var(--muted);font-size:11px}\n.dur-v{display:inline-flex;align-items:baseline;white-space:nowrap}\n.dn{font-size:28px;font-weight:700;color:var(--accent);line-height:1.1;font-variant-numeric:tabular-nums}\n.du{font-size:12px;color:var(--muted);margin:0 3px 0 1px}\n.dur-m{margin-left:auto;color:var(--muted);font-size:11px;white-space:nowrap}\n.tl{display:flex;gap:1px;height:6px;border-radius:3px;overflow:hidden;background:var(--soft);flex:none}\n.seg{display:block;min-width:1px;background:var(--accent);border-radius:1px}\n.seg:nth-child(even){background:var(--accent-alt);opacity:.85}\n\n.row{flex:none;display:grid;grid-template-columns:32px minmax(0,1fr);gap:6px;padding:6px 7px;border-radius:9px;background:var(--panel-paper);border:1px solid var(--line)}\n.row-h{display:flex;flex-direction:column;align-items:center;gap:2px}\n.ix{width:20px;height:20px;border-radius:50%;background:var(--accent);color:var(--on-accent);font-size:11px;font-weight:700;display:grid;place-items:center}\n.rs{color:var(--muted);font-size:10.5px;white-space:nowrap}\n.row-b{min-width:0;display:flex;flex-direction:column;gap:2px}\n.rv,.rl{overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;word-break:break-word;white-space:pre-wrap}\n.rv{font-weight:600}\n.rl{color:var(--muted)}\n.rv.none,.rl.none{font-weight:400;font-style:italic;opacity:.75}\n.none-l{color:var(--muted);font-size:11.5px;padding:8px 2px;text-align:center}\n\n.empty{flex:1;min-height:0;display:flex;flex-direction:column;justify-content:center;gap:8px;text-align:center}\n.empty-t{font-weight:700;font-size:15px}\n.empty-s{color:var(--muted);font-size:11.5px}\n.empty .btn{flex:none}\n\n.card[data-size=\"3x3\"] .dn{font-size:26px}\n.card[data-size=\"3x6\"] .list,.card[data-size=\"6x3\"] .list,.card[data-size=\"6x6\"] .list{display:flex}\n.card[data-size=\"6x3\"] .home{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);grid-template-rows:minmax(0,1fr) auto;grid-template-areas:\"top list\" \"act list\";column-gap:10px;row-gap:8px}\n.card[data-size=\"6x3\"] .top{flex:none}\n.card[data-size=\"6x6\"] .ttl{font-size:18px}\n.card[data-size=\"6x6\"] .dn{font-size:34px}\n.card[data-size=\"6x6\"] .tl{height:8px}\n.card[data-size=\"6x6\"] .row{grid-template-columns:40px minmax(0,1fr);padding:8px 10px}\n.card[data-size=\"6x6\"] .row-b{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px}\n\n\n.bar{display:flex;align-items:center;gap:6px;flex:none;min-width:0}\n.bar .btn{flex:none;padding:0 10px}\n.grow{flex:1;min-width:0;font-weight:700;text-align:center;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}\n.tot{flex:none;display:flex;justify-content:space-between;align-items:baseline;gap:6px;color:var(--muted);font-size:11px;padding:0 2px}\n.tot-v{color:var(--accent);font-weight:700;font-size:13px}\n.err{flex:none;color:var(--ink);background:var(--soft);border-left:3px solid var(--accent);padding:4px 6px;border-radius:6px;font-size:11px;word-break:break-word}\n.body{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n\n.fld{min-width:0}\n.fld-l{display:block;color:var(--muted);font-size:11px;margin-bottom:2px}\n.inp,.ta,.sec{width:100%;min-width:0;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);padding:5px 7px;font-size:12px}\n.inp:focus,.ta:focus,.sec:focus{outline:2px solid var(--accent);outline-offset:0}\n.ta{display:block;resize:vertical;height:48px;min-height:40px;line-height:1.35}\n.sec{width:50px;flex:none;text-align:center;padding:3px 4px;-moz-appearance:textfield;appearance:textfield}\n.sec::-webkit-outer-spin-button,.sec::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}\n\n.shot{flex:none;display:flex;flex-direction:column;gap:6px;padding:7px;border-radius:10px;border:1px solid var(--line);background:var(--soft)}\n.shot-h{display:flex;align-items:center;flex-wrap:wrap;gap:4px 6px;min-width:0}\n.shot-ix{font-weight:700;color:var(--accent);white-space:nowrap}\n.secw{display:inline-flex;align-items:center;gap:3px}\n.unit{color:var(--muted);font-size:11px;white-space:nowrap}\n.tools{display:inline-flex;gap:4px;margin-left:auto}\n.shot-f{display:grid;grid-template-columns:minmax(0,1fr);gap:6px}\n.card[data-size=\"6x3\"] .shot-f,.card[data-size=\"6x6\"] .shot-f{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}\n.card[data-size=\"6x6\"] .ta{height:72px}\n\n.ib{flex:none;width:26px;height:26px;padding:0;border-radius:7px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);cursor:pointer;display:grid;place-items:center;font-size:14px;line-height:1}\n.ib:disabled{opacity:.35;cursor:default}\n\n.lrow{flex:none;display:flex;align-items:stretch;gap:5px;min-width:0}\n.pick{flex:1;min-width:0;text-align:left;display:flex;flex-direction:column;gap:2px;padding:6px 8px;border-radius:10px;border:1px solid var(--line);background:var(--panel-paper);cursor:pointer}\n.pick.on{border-color:var(--accent);background:var(--soft)}\n.pick-r{display:flex;align-items:center;gap:5px;min-width:0}\n.pick-t{min-width:0;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.cur{flex:none;font-size:10px;font-weight:700;color:var(--on-accent);background:var(--accent);border-radius:5px;padding:0 5px}\n.pick-m{color:var(--muted);font-size:11px;overflow-wrap:anywhere}\n.lrow .ib{height:auto;align-self:stretch;min-height:36px}\n.cbox{flex:none;display:flex;flex-direction:column;gap:6px;padding:8px;border-radius:10px;border:1px solid var(--accent);background:var(--soft)}\n.cbox-t{overflow-wrap:anywhere}\n";
function secOf(v){
  const n=Math.round(Number(v));
  return isFinite(n)&&n>0?Math.min(n,3600):0;
}
function shotsOf(sc){
  return sc&&Array.isArray(sc.shots)?sc.shots:[];
}
function totalOf(shots){
  let t=0;
  (shots||[]).forEach(function(sh){t+=secOf(sh.sec);});
  return t;
}
function durParts(total){
  total=Math.max(0,Math.round(total||0));
  const h=Math.floor(total/3600),m=Math.floor(total%3600/60),s=total%60;
  const out=[];
  if(h>0)out.push([String(h),'时']);
  if(h>0||m>0)out.push([String(m),'分']);
  if(s>0||total===0)out.push([String(s),'秒']);
  return out;
}
function durText(total){
  return durParts(total).map(function(p){return p[0]+p[1];}).join('');
}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day}=ctx;
  const scripts=Array.isArray(state.scripts)?state.scripts:[];
  const cur=scripts.find(function(x){return x.id===state.selectedId;})||scripts[0]||null;
  const view=ui.view||'home';
  let afterMount=null;

  const btn=function(label,cls,fn,extra){
    const a={type:'button',class:'btn '+cls,onclick:fn};
    if(extra)for(const k in extra)a[k]=extra[k];
    return el('button',a,label);
  };
  const fail=function(msg){ui.err=msg;ui.saving=false;redraw();};

  function goHome(){
    ui.view='home';ui.draft=null;ui.err='';ui.confirmDiscard=false;ui.confirmDel=null;ui.saving=false;
    redraw();
  }
  function openLib(){
    ui.view='lib';ui.err='';ui.confirmDel=null;
    redraw();
  }
  function startNew(){
    ui.draft={id:uid(),title:'',isNew:true,shots:[{id:uid(),visual:'',line:'',sec:''}]};
    ui.orig=JSON.stringify(ui.draft);
    ui.view='edit';ui.err='';ui.scroll=0;ui.confirmDiscard=false;ui.saving=false;
    redraw();
  }
  function startEdit(){
    if(!cur)return;
    ui.draft={
      id:cur.id,title:cur.title||'',isNew:false,
      shots:shotsOf(cur).map(function(sh){
        return {id:sh.id||uid(),visual:sh.visual||'',line:sh.line||'',sec:secOf(sh.sec)>0?String(secOf(sh.sec)):''};
      })
    };
    ui.orig=JSON.stringify(ui.draft);
    ui.view='edit';ui.err='';ui.scroll=0;ui.confirmDiscard=false;ui.saving=false;
    redraw();
  }
  function goBack(){
    const d=ui.draft;
    if(d&&JSON.stringify(d)!==ui.orig&&!ui.confirmDiscard){
      ui.confirmDiscard=true;redraw();return;
    }
    goHome();
  }
  function save(){
    const d=ui.draft;
    if(!d||ui.saving)return;
    for(let i=0;i<d.shots.length;i++){
      const t=String(d.shots[i].sec).trim();
      if(t!==''){
        const n=Number(t);
        if(!isFinite(n)||n<0||n>3600){
          ui.err='镜头 '+(i+1)+' 的秒数需要是 0 到 3600 之间的数字';
          redraw();return;
        }
      }
    }
    const rec={
      id:d.id,title:d.title.trim(),updated:day(),
      shots:d.shots.map(function(sh){return {id:sh.id,visual:sh.visual,line:sh.line,sec:secOf(sh.sec)};})
    };
    ui.saving=true;ui.err='';
    commit(function(s){
      const list=Array.isArray(s.scripts)?s.scripts.slice():[];
      const i=list.findIndex(function(x){return x.id===rec.id;});
      if(i>=0)list[i]=rec;else list.unshift(rec);
      return Object.assign({},s,{scripts:list,selectedId:rec.id});
    },{view:'home'}).catch(function(){fail('保存失败，请重试');});
  }
  function pick(id){
    if(cur&&cur.id===id){goHome();return;}
    commit(function(s){return Object.assign({},s,{selectedId:id});},{view:'home'})
      .catch(function(){fail('切换失败，请重试');});
  }
  function doDelete(id){
    commit(function(s){
      const list=(Array.isArray(s.scripts)?s.scripts:[]).filter(function(x){return x.id!==id;});
      const sel=s.selectedId===id?(list[0]?list[0].id:null):s.selectedId;
      return Object.assign({},s,{scripts:list,selectedId:sel});
    },{view:'lib'}).catch(function(){fail('删除失败，请重试');});
  }


  function renderHome(){
    if(!cur){
      return el('div',{class:'empty'},
        el('div',{class:'empty-t'},'还没有视频脚本'),
        el('div',{class:'empty-s'},'新建后可逐个镜头记录画面、台词和大概秒数，并随时调整顺序。'),
        btn('新建脚本','primary',startNew));
    }
    const shots=shotsOf(cur);
    const total=totalOf(shots);
    const tl=el('div',{class:'tl','aria-hidden':'true'});
    shots.forEach(function(sh){
      const g=el('i',{class:'seg'});
      g.style.flex=(secOf(sh.sec)||0.4)+' 1 0%';
      tl.append(g);
    });
    const dv=el('span',{class:'dur-v'});
    durParts(total).forEach(function(p){
      dv.append(el('span',{class:'dn'},p[0]),el('span',{class:'du'},p[1]));
    });
    const top=el('div',{class:'top'},
      el('div',{class:'ttl'+(cur.title?'':' untitled')},cur.title||'未命名脚本'),
      el('div',{class:'dur'},
        el('span',{class:'dur-l'},'总时长'),dv,
        el('span',{class:'dur-m'},shots.length+' 个镜头')),
      tl);
    const list=el('div',{class:'list'});
    if(!shots.length)list.append(el('div',{class:'none-l'},'这个脚本还没有镜头，点「编辑」添加。'));
    shots.forEach(function(sh,i){
      list.append(el('div',{class:'row'},
        el('div',{class:'row-h'},
          el('span',{class:'ix'},String(i+1)),
          el('span',{class:'rs'},secOf(sh.sec)+'秒')),
        el('div',{class:'row-b'},
          el('div',{class:'rv'+(sh.visual?'':' none')},sh.visual||'（未写画面）'),
          el('div',{class:'rl'+(sh.line?'':' none')},sh.line?('“'+sh.line+'”'):'（未写台词）'))));
    });
    const actions=el('div',{class:'actions'},
      btn('编辑','primary',startEdit),
      btn('脚本库 '+scripts.length,'',openLib));
    return el('div',{class:'home'},top,list,actions);
  }

  function renderLib(){
    const box=el('div',{class:'lib'});
    box.append(el('div',{class:'bar'},
      btn('返回','',goHome),
      el('span',{class:'grow'},'脚本库'),
      btn('新建','primary',startNew)));
    if(ui.err)box.append(el('div',{class:'err',role:'alert'},'出错：'+ui.err));
    const body=el('div',{class:'body'});
    if(!scripts.length)body.append(el('div',{class:'none-l'},'脚本库是空的，点「新建」写第一个脚本。'));
    scripts.forEach(function(sc){
      const name=sc.title||'未命名脚本';
      if(ui.confirmDel===sc.id){
        body.append(el('div',{class:'cbox'},
          el('div',{class:'cbox-t'},'删除「'+name+'」？删除后无法恢复。'),
          el('div',{class:'actions'},
            btn('确认删除','primary',function(){doDelete(sc.id);}),
            btn('取消','',function(){ui.confirmDel=null;redraw();}))));
        return;
      }
      const on=!!cur&&cur.id===sc.id;
      const sh=shotsOf(sc);
      const tr=el('span',{class:'pick-r'});
      if(on)tr.append(el('span',{class:'cur'},'当前'));
      tr.append(el('span',{class:'pick-t'},name));
      const meta=sh.length+' 镜 · '+durText(totalOf(sh))+(sc.updated?' · '+String(sc.updated).slice(5):'');
      body.append(el('div',{class:'lrow'},
        el('button',{type:'button',class:'pick'+(on?' on':''),'aria-pressed':on?'true':'false',onclick:function(){pick(sc.id);}},
          tr,el('span',{class:'pick-m'},meta)),
        el('button',{type:'button',class:'ib del','aria-label':'删除 '+name,title:'删除',onclick:function(){ui.confirmDel=sc.id;redraw();}},'×')));
    });
    box.append(body);
    return box;
  }


  function renderEdit(){
    const d=ui.draft;
    if(!d)return renderHome();
    const totV=el('span',{class:'tot-v'},durText(totalOf(d.shots)));
    const upd=function(){totV.textContent=durText(totalOf(d.shots));};
    const shotEls={};
    let focusTa=null;

    function field(label,val,ph,key,sh){
      const ta=el('textarea',{class:'ta',rows:'2',placeholder:ph,'aria-label':label,oninput:function(e){sh[key]=e.target.value;}});
      ta.value=val;
      return {box:el('div',{class:'fld'},el('span',{class:'fld-l'},label),ta),ta:ta};
    }
    function mkShot(sh,i){
      const move=function(dir){
        return function(){
          const j=i+dir;
          if(j<0||j>=d.shots.length)return;
          const t=d.shots[i];d.shots[i]=d.shots[j];d.shots[j]=t;
          ui.focusShot=sh.id;ui.focusNew=false;
          redraw();
        };
      };
      const sec=el('input',{class:'sec',type:'number',min:'0',max:'3600',step:'1',placeholder:'0','aria-label':'镜头 '+(i+1)+' 大概几秒',oninput:function(e){sh.sec=e.target.value;upd();}});
      sec.value=sh.sec;
      const fv=field('画面',sh.visual,'这一镜拍什么、怎么拍','visual',sh);
      const fl=field('台词',sh.line,'旁白或对白','line',sh);
      if(ui.focusShot===sh.id&&ui.focusNew)focusTa=fv.ta;
      const card=el('div',{class:'shot'},
        el('div',{class:'shot-h'},
          el('span',{class:'shot-ix'},'镜头 '+(i+1)),
          el('span',{class:'secw'},sec,el('span',{class:'unit'},'秒')),
          el('span',{class:'tools'},
            el('button',{type:'button',class:'ib','aria-label':'上移镜头 '+(i+1),title:'上移',disabled:i===0,onclick:move(-1)},'↑'),
            el('button',{type:'button',class:'ib','aria-label':'下移镜头 '+(i+1),title:'下移',disabled:i===d.shots.length-1,onclick:move(1)},'↓'),
            el('button',{type:'button',class:'ib del','aria-label':'删除镜头 '+(i+1),title:'删除',onclick:function(){d.shots.splice(i,1);redraw();}},'×'))),
        el('div',{class:'shot-f'},fv.box,fl.box));
      shotEls[sh.id]=card;
      return card;
    }

    const titleIn=el('input',{class:'inp',type:'text',maxlength:'60',placeholder:'脚本标题','aria-label':'脚本标题',oninput:function(e){d.title=e.target.value;}});
    titleIn.value=d.title;
    const body=el('div',{class:'body',onscroll:function(e){ui.scroll=e.target.scrollTop;}});
    body.append(el('div',{class:'fld'},el('span',{class:'fld-l'},'脚本标题'),titleIn));
    if(!d.shots.length)body.append(el('div',{class:'none-l'},'还没有镜头，点下方「添加镜头」。'));
    d.shots.forEach(function(sh,i){body.append(mkShot(sh,i));});
    body.append(btn('+ 添加镜头','add',function(){
      const id=uid();
      d.shots.push({id:id,visual:'',line:'',sec:''});
      ui.focusShot=id;ui.focusNew=true;
      redraw();
    }));

    const box=el('div',{class:'edit'});
    box.append(el('div',{class:'bar'},
      btn(ui.confirmDiscard?'放弃修改?':'返回','',goBack),
      el('span',{class:'grow'},d.isNew?'新建脚本':'编辑脚本'),
      btn('保存','primary',save)));
    box.append(el('div',{class:'tot'},el('span',{},'总时长 ',totV),el('span',{},d.shots.length+' 个镜头')));
    if(ui.err)box.append(el('div',{class:'err',role:'alert'},'出错：'+ui.err));
    box.append(body);

    const fs=ui.focusShot,target=fs?shotEls[fs]:null,ft=focusTa;
    ui.focusShot=null;ui.focusNew=false;
    afterMount=function(){
      const apply=function(){
        body.scrollTop=ui.scroll||0;
        if(target)target.scrollIntoView({block:'nearest'});
        if(ft)ft.focus();
      };
      apply();
      setTimeout(apply,0);
    };
    return box;
  }

  const node=view==='edit'?renderEdit():(view==='lib'?renderLib():renderHome());
  root.append(node);
  if(afterMount)afterMount();
